package org.gamescaling.craftbridge.v5;
import org.objectweb.asm.*;
public class VerifyRestoreTest {
 static class L extends ClassLoader {L(){super(VerifyRestoreTest.class.getClassLoader());}Class<?> make(byte[] b){return defineClass(null,b,0,b.length);}}
 static boolean eval(byte[] b,long win,int key)throws Exception{return (boolean)new L().make(b).getMethod("isKeyDown",long.class,int.class).invoke(null,win,key);}
 public static void main(String[] args)throws Exception{
  ClassWriter w=new ClassWriter(0);w.visit(Opcodes.V21,Opcodes.ACC_PUBLIC,"MissingFramesInput",null,"java/lang/Object",null);
  MethodVisitor m=w.visitMethod(Opcodes.ACC_PUBLIC|Opcodes.ACC_STATIC,"isKeyDown","(JI)Z",null,null);m.visitCode();Label no=new Label();m.visitVarInsn(Opcodes.ILOAD,2);m.visitIntInsn(Opcodes.BIPUSH,17);m.visitJumpInsn(Opcodes.IF_ICMPNE,no);m.visitInsn(Opcodes.ICONST_1);m.visitInsn(Opcodes.IRETURN);m.visitLabel(no);m.visitInsn(Opcodes.ICONST_0);m.visitInsn(Opcodes.IRETURN);m.visitMaxs(2,3);m.visitEnd();w.visitEnd();byte[] original=w.toByteArray();
  boolean reproduced=false;try{eval(original,1,99);}catch(VerifyError e){reproduced=true;System.out.println("Legacy restore failure reproduced: "+e.getMessage().split("\\n")[0]);}if(!reproduced)throw new AssertionError("Fixture did not reproduce VerifyError");
  System.setProperty("gamescaling.v5.key.99","true");byte[] patched=InputKeyTransform.rewrite(original,VerifyRestoreTest.class.getClassLoader(),true),restored=InputKeyTransform.rewrite(original,VerifyRestoreTest.class.getClassLoader(),false);
  if(!eval(patched,1,99)||!eval(patched,1,17)||eval(restored,1,99)||!eval(restored,1,17))throw new AssertionError("Input semantics incorrect");byte[] stacked=InputKeyTransform.rewrite(patched,VerifyRestoreTest.class.getClassLoader(),true),clean=InputKeyTransform.rewrite(stacked,VerifyRestoreTest.class.getClassLoader(),false);if(eval(clean,1,99)||!eval(clean,1,17))throw new AssertionError("Residual hook survived restore");System.clearProperty("gamescaling.v5.key.99");
  ClassWriter bad=new ClassWriter(0);bad.visit(Opcodes.V21,Opcodes.ACC_PUBLIC,"MalformedLegacyInput",null,"java/lang/Object",null);MethodVisitor v=bad.visitMethod(Opcodes.ACC_PUBLIC|Opcodes.ACC_STATIC,"isKeyDown","(JI)Z",null,null);v.visitCode();Label falseLabel=new Label(),join=new Label();v.visitVarInsn(Opcodes.ILOAD,2);v.visitIntInsn(Opcodes.BIPUSH,17);v.visitJumpInsn(Opcodes.IF_ICMPNE,falseLabel);v.visitInsn(Opcodes.ICONST_1);v.visitJumpInsn(Opcodes.GOTO,join);v.visitLabel(falseLabel);v.visitFrame(Opcodes.F_CHOP,2,null,0,null);v.visitInsn(Opcodes.ICONST_0);v.visitLabel(join);v.visitFrame(Opcodes.F_SAME1,0,null,1,new Object[]{Opcodes.INTEGER});v.visitLdcInsn("gamescaling.v4.key.");v.visitVarInsn(Opcodes.ILOAD,2);v.visitMethodInsn(Opcodes.INVOKESTATIC,"java/lang/Integer","toString","(I)Ljava/lang/String;",false);v.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"java/lang/String","concat","(Ljava/lang/String;)Ljava/lang/String;",false);v.visitMethodInsn(Opcodes.INVOKESTATIC,"java/lang/Boolean","getBoolean","(Ljava/lang/String;)Z",false);v.visitInsn(Opcodes.IOR);v.visitInsn(Opcodes.IRETURN);v.visitMaxs(3,3);v.visitEnd();bad.visitEnd();byte[] malformed=bad.toByteArray();boolean badFrame=false;try{eval(malformed,1,99);}catch(VerifyError e){badFrame=true;System.out.println("Observed CHOP-frame failure reproduced: "+e.getMessage().split("\\n")[0]);}if(!badFrame)throw new AssertionError("Malformed frame unexpectedly verified");System.setProperty("gamescaling.v4.key.99","true");System.setProperty("gamescaling.v5.key.99","true");byte[] cleanLegacy=InputKeyTransform.rewrite(malformed,VerifyRestoreTest.class.getClassLoader(),false);if(eval(cleanLegacy,1,99)||!eval(cleanLegacy,1,17))throw new AssertionError("Legacy patch not fully removed");System.clearProperty("gamescaling.v4.key.99");System.clearProperty("gamescaling.v5.key.99");
  System.out.println("PASS: install enables virtual key; restored bytecode ignores virtual property and preserves original key semantics");
 }
}
